-- Release57 beta connector: existing daily campaign/allocator/credit source/ledger only.
-- Candidate NOT APPLIED. No campaign edit, daily allocation, credit issuance or existing row backfill.
-- Requires core and scope candidates first. Existing humanities behavior remains exact.
begin;
set local lock_timeout='5s';set local statement_timeout='180s';
select pg_advisory_xact_lock(hashtextextended('legendstudy-release57-beta-connection',71659));
create temporary table release57_beta_functions_before on commit drop as
select p.oid,p.proowner,p.proacl,p.proconfig,p.prosecdef from pg_proc p where p.oid in('essay_beta_private.eligible(uuid,uuid)'::regprocedure,'essay_beta_private.credit_source(uuid,uuid)'::regprocedure,'public.math_session_submit(uuid,uuid,uuid[],uuid)'::regprocedure);
create temporary table release57_beta_scope_before on commit drop as select * from essay_beta_private.exam_scope;
create temporary table release57_beta_campaign_before on commit drop as select id,md5(to_jsonb(c)::text) hash from essay_beta_private.campaigns c;
do $guard$ declare e jsonb; a record; begin
 if current_user<>'postgres' then raise exception 'RELEASE57_REQUIRES_POSTGRES_ROLE';end if;
 for e in select value from jsonb_array_elements($snapshot$[{"schema": "essay_beta_private", "name": "eligible", "args": "p_grant uuid, p_exam uuid", "owner": "postgres", "acl": "{postgres=X/postgres}", "proconfig": ["search_path=\"\""], "hash": "5cc8547ed15874d932d84e6d74009552"}, {"schema": "essay_beta_private", "name": "credit_source", "args": "p_account uuid, p_exam uuid", "owner": "postgres", "acl": "{postgres=X/postgres}", "proconfig": ["search_path=\"\""], "hash": "09fc9d66ee9286fac0f6bfed03046d3b"}, {"schema": "public", "args": "p_exam uuid, p_key uuid, p_attempts uuid[], p_parent uuid", "owner": "postgres", "acl": "{postgres=X/postgres,authenticated=X/postgres}", "hash": "03456f71b861151cfe523c06a075d8ca", "name": "math_session_submit", "proconfig": ["search_path=\"\""]}]$snapshot$::jsonb) loop
 select md5(pg_get_functiondef(p.oid)) hash,pg_get_userbyid(p.proowner) owner,p.proacl::text acl,to_jsonb(p.proconfig) config into a from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname=e->>'schema' and p.proname=e->>'name' and pg_get_function_identity_arguments(p.oid)=e->>'args';
 if not found or a.hash is distinct from e->>'hash' or a.owner is distinct from e->>'owner' or a.acl is distinct from e->>'acl' or a.config is distinct from e->'proconfig' then raise exception 'RELEASE57_BETA_SOURCE_DRIFT: %',e->>'name';end if;
 end loop;
